const crypto = require('crypto');
const item = $('Meta webhook').first();
const raw = item.binary?.data ? Buffer.from(item.binary.data.data, 'base64').toString() : JSON.stringify(item.json.body || {});
const expected = 'sha256=' + crypto.createHmac('sha256', 'k').update(raw).digest('hex');
const ok = String(item.json.headers['x-hub-signature-256'] || '') === expected;
return [{ json: { ok } }];
